mapper.update:
UPDATE work_invitations
SET token_hash = #{tokenHash}
WHERE id = #{invitationId}
  AND status = 'PENDING'

UPDATE work_invitations
SET status = 'EXPIRED'
WHERE work_case_id = #{workCaseId}
  AND status = 'PENDING'
  AND expires_at <= #{now}

UPDATE work_invitations
SET status = 'REVOKED',
    revoked_at = #{revokedAt}
WHERE work_case_id = #{workCaseId}
  AND status = 'PENDING'
